/**
 * A split hero: a badge, the heading, a lead, an extra under it and one or two actions, beside the media. Axes:
 * extra (stats: three figures, avatars: faces and a proof line, minis: two small feature cards, quote: a quote
 * over three figures, none), media (picture, card: a floating card on the picture, grid: four pictures with
 * captions, plans: two plan cards on the picture), mediaSide, tone.
 */
import { type ReactNode } from "react";
import { ActionGroup } from "../components/action-group";
import { HeroSplitExtras } from "../components/hero-split-extras";
import { HeroSplitMedia } from "../components/hero-split-media";
import { SectionFrame } from "../components/section-frame";
import type { HeroContent } from "./hero-split.types";
import type { Stat } from "./stats-band.types";
import type { Feature } from "./feature-grid.types";
import type { Quote } from "./testimonial-grid.types";
import type { OfferCard } from "./store-hero.types";
import type { Plan } from "./pricing-card.types";
import type { LinkActions } from "./error-page.types";

export type HeroSplitProps = {
  id: string;
  title: string;
  lead?: string;
  badge?: string;
  level?: 1 | 2;
  actions: LinkActions;
  content: HeroContent;
  extra?: "stats" | "avatars" | "minis" | "quote" | "none";
  media?: "picture" | "card" | "grid" | "plans";
  mediaSide?: "end" | "start";
  tone?: "default" | "muted";
};

export function HeroSplit({
  id,
  title,
  lead = "",
  badge = "",
  level = 1,
  actions,
  content,
  extra = "stats",
  media = "picture",
  mediaSide = "end",
  tone = "default",
}: HeroSplitProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      lead={lead}
      heading={{ badge, level }}
      layout="split"
      media={{ show: true, side: mediaSide }}
      tone={tone}
      density="default"
      aside={(
        <HeroSplitMedia content={content} alt={title} media={media} />
      )}
    >
      <HeroSplitExtras content={content} extra={extra} />
      <ActionGroup
        primary={actions.cta}
        primaryHref={actions.href}
        secondary={((actions.mode === "two") ? actions.secondary : undefined)}
        secondaryHref={actions.secondaryHref}
        align="start"
      />
    </SectionFrame>
  );
}

